import { test, expect } from '@playwright/test';
import { prepareReadOnly, openCalculator, fillInputs, expectResult, SET1 } from './calculator.helpers';

test.use({ serviceWorkers: 'block' });

test.describe('Калькулятор — экран', () => {
  test('Мобайл: без горизонтального скролла, форма над результатами #3e4835 @android @prod-safe', async ({ page, context }) => {
    await prepareReadOnly(context);
    await openCalculator(page);
    await fillInputs(page, SET1);
    await expectResult(page, 'תזרים חודשי משוער', '14,250 ₪');

    const widths = await page.evaluate(() => ({ doc: document.documentElement.scrollWidth, win: window.innerWidth }));
    expect(widths.doc, 'нет горизонтальной прокрутки').toBeLessThanOrEqual(widths.win);

    const top = (name: string) =>
      page
        .getByRole('heading', { level: 2, name, exact: true })
        .evaluate((el) => el.getBoundingClientRect().top + window.scrollY);
    expect(await top('השקעה ראשונית'), 'форма выше результатов').toBeLessThan(await top('תוצאות'));
  });
});
